// `./app calc`: see the "calc" section of SPEC.md.
package calc

import "core:bufio"
import "core:fmt"
import "core:os"
import "core:strconv"
import "core:strings"

import "../ioutil"

// Reads standard input, writes standard output and returns the exit status.
//
// Every line of input is evaluated independently and its value (or `error`)
// is printed on its own line; blank lines produce no output.
run :: proc() -> (exit_code: int) {
	data, read_err := ioutil.read_all(os.stdin)
	if read_err != nil {
		fmt.eprintln("calc: reading standard input:", read_err)
		return 1
	}
	defer delete(data)

	out: bufio.Writer
	bufio.writer_init(&out, os.to_writer(os.stdout), 64 * 1024)
	defer bufio.writer_destroy(&out)

	ev: Evaluator
	defer evaluator_destroy(&ev)

	num_buf: [32]byte
	input := string(data)
	for line in strings.split_iterator(&input, "\n") {
		if is_blank(line) {
			continue
		}
		if value, ok := evaluate(&ev, line); ok {
			bufio.writer_write_string(&out, strconv.write_int(num_buf[:], value, 10))
		} else {
			bufio.writer_write_string(&out, "error")
		}
		bufio.writer_write_byte(&out, '\n')
	}

	if err := bufio.writer_flush(&out); err != nil {
		fmt.eprintln("calc: writing standard output:", err)
		return 1
	}
	return 0
}

@(private = "file")
is_blank :: proc(line: string) -> bool {
	for c in transmute([]byte)line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

package calc

import "base:intrinsics"

// Iterative operator-precedence evaluator for the grammar in SPEC.md:
//
//     expr    := term    (('+' | '-') term)*
//     term    := unary   (('*' | '/' | '%') unary)*
//     unary   := '-' unary | primary
//     primary := NUMBER | '(' expr ')'
//
// Explicit operand/operator stacks are used instead of recursion so that
// arbitrarily deep nesting (`((((…))))`, `----…1`) cannot exhaust the call
// stack. The stacks are kept in the Evaluator and reused across lines.
@(private)
Evaluator :: struct {
	values:    [dynamic]i64,
	operators: [dynamic]Operator,
}

@(private)
evaluator_destroy :: proc(ev: ^Evaluator) {
	delete(ev.values)
	delete(ev.operators)
}

@(private = "file")
Operator :: enum u8 {
	Left_Paren, // marker on the operator stack, never applied
	Add,
	Sub,
	Mul,
	Div,
	Rem,
	Neg,
}

// Binding strength; higher binds tighter. Left_Paren is lowest so that it
// stops reductions triggered by binary operators.
@(private = "file", rodata)
PRECEDENCE := [Operator]u8 {
	.Left_Paren = 0,
	.Add        = 1,
	.Sub        = 1,
	.Mul        = 2,
	.Div        = 2,
	.Rem        = 2,
	.Neg        = 3,
}

// Evaluates one line. `ok` is false on any syntax error, division by zero
// or 64-bit overflow.
@(private)
evaluate :: proc(ev: ^Evaluator, line: string) -> (value: i64, ok: bool) {
	clear(&ev.values)
	clear(&ev.operators)

	// The parser alternates between expecting an operand (a number, `(` or
	// unary `-`) and expecting an operator (a binary operator or `)`).
	expect_operand := true
	i := 0
	for i < len(line) {
		c := line[i]
		switch {
		case c == ' ' || c == '\t':
			i += 1

		case expect_operand:
			switch c {
			case '0' ..= '9':
				n: i64
				n, i = parse_number(line, i) or_return
				append(&ev.values, n)
				expect_operand = false
			case '(':
				append(&ev.operators, Operator.Left_Paren)
				i += 1
			case '-':
				append(&ev.operators, Operator.Neg)
				i += 1
			case:
				return 0, false
			}

		case:
			op: Operator
			switch c {
			case '+': op = .Add
			case '-': op = .Sub
			case '*': op = .Mul
			case '/': op = .Div
			case '%': op = .Rem
			case ')':
				reduce(ev, PRECEDENCE[.Left_Paren] + 1) or_return
				if len(ev.operators) == 0 {
					return 0, false // unbalanced `)`
				}
				pop(&ev.operators) // the matching Left_Paren
				i += 1
				continue
			case:
				return 0, false
			}
			// All binary operators are left-associative: first apply every
			// pending operator that binds at least as tightly.
			reduce(ev, PRECEDENCE[op]) or_return
			append(&ev.operators, op)
			expect_operand = true
			i += 1
		}
	}

	if expect_operand {
		return 0, false // empty input or missing operand
	}
	reduce(ev, PRECEDENCE[.Left_Paren] + 1) or_return
	if len(ev.operators) != 0 {
		return 0, false // unbalanced `(`
	}
	assert(len(ev.values) == 1)
	return ev.values[0], true
}

// Parses the run of decimal digits starting at `start`; fails if the literal
// does not fit in an i64.
@(private = "file")
parse_number :: proc(line: string, start: int) -> (value: i64, end: int, ok: bool) {
	end = start
	for end < len(line) && line[end] >= '0' && line[end] <= '9' {
		digit := i64(line[end] - '0')
		overflow_mul, overflow_add: bool
		value, overflow_mul = intrinsics.overflow_mul(value, 10)
		value, overflow_add = intrinsics.overflow_add(value, digit)
		if overflow_mul || overflow_add {
			return 0, end, false
		}
		end += 1
	}
	return value, end, true
}

// Applies operators from the top of the stack while their precedence is at
// least `min_precedence`.
@(private = "file")
reduce :: proc(ev: ^Evaluator, min_precedence: u8) -> (ok: bool) {
	for len(ev.operators) > 0 {
		op := ev.operators[len(ev.operators) - 1]
		if PRECEDENCE[op] < min_precedence {
			break
		}
		pop(&ev.operators)

		if op == .Neg {
			top := &ev.values[len(ev.values) - 1]
			top^ = apply_neg(top^) or_return
			continue
		}

		rhs := pop(&ev.values)
		lhs := &ev.values[len(ev.values) - 1]
		lhs^ = apply_binary(op, lhs^, rhs) or_return
	}
	return true
}

@(private = "file")
apply_neg :: proc(x: i64) -> (result: i64, ok: bool) {
	if x == min(i64) {
		return 0, false
	}
	return -x, true
}

@(private = "file")
apply_binary :: proc(op: Operator, lhs, rhs: i64) -> (result: i64, ok: bool) {
	overflow: bool
	#partial switch op {
	case .Add:
		result, overflow = intrinsics.overflow_add(lhs, rhs)
	case .Sub:
		result, overflow = intrinsics.overflow_sub(lhs, rhs)
	case .Mul:
		result, overflow = intrinsics.overflow_mul(lhs, rhs)
	case .Div:
		if rhs == 0 || (lhs == min(i64) && rhs == -1) {
			return 0, false
		}
		result = lhs / rhs
	case .Rem:
		if rhs == 0 {
			return 0, false
		}
		// min(i64) % -1 is mathematically 0 but traps on most hardware.
		result = rhs == -1 ? 0 : lhs % rhs
	case:
		unreachable()
	}
	return result, !overflow
}

// Helpers shared by the subcommands for reading their input.
package ioutil

import "core:os"

@(private = "file")
READ_CHUNK :: 64 * 1024

// Reads `f` to end of file.
//
// Unlike `os.read_entire_file`, this does not trust the size reported by the
// file: for a pipe that is only what is currently buffered in it, so a
// size-driven read would silently truncate the input.
read_all :: proc(f: ^os.File, allocator := context.allocator) -> (data: []byte, err: os.Error) {
	buf := make([dynamic]byte, 0, READ_CHUNK, allocator) or_return
	defer if err != nil {
		delete(buf)
		data = nil
	}

	for {
		if cap(buf) - len(buf) < READ_CHUNK {
			reserve(&buf, 2 * cap(buf)) or_return
		}
		start := len(buf)
		resize(&buf, cap(buf)) or_return
		n, read_err := os.read(f, buf[start:])
		resize(&buf, start + n) or_return

		switch read_err {
		case nil:
			if n == 0 {
				return buf[:], nil
			}
		case .EOF, .Broken_Pipe:
			return buf[:], nil
		case:
			return nil, read_err
		}
	}
}

package lru

// An LRU cache of string keys to string values.
//
// Entries live in a pool of nodes linked into a doubly-linked recency list by
// index; slot 0 is a sentinel whose `next` is the most recently used entry and
// whose `prev` is the least recently used one. A map from key to node index
// gives O(1) expected lookup. Evicted and deleted slots are recycled through a
// free list, so the pool never grows beyond the largest number of keys held
// at once (plus the sentinel).
//
// Keys and values are not copied: the caller must keep the memory they point
// into alive for as long as the cache is in use.

@(private)
Node_Index :: distinct u32

@(private)
SENTINEL :: Node_Index(0)

@(private)
Node :: struct {
	key:   string,
	value: string,
	prev:  Node_Index,
	next:  Node_Index,
}

@(private)
Cache :: struct {
	capacity: int,
	nodes:    [dynamic]Node,
	index:    map[string]Node_Index,
	// Head of the free list of recycled slots, chained through `next`;
	// SENTINEL when empty.
	free:     Node_Index,
}

// `expected_keys` is a hint used to pre-size the storage.
@(private)
cache_init :: proc(c: ^Cache, capacity: int, expected_keys: int, allocator := context.allocator) {
	assert(capacity >= 1)
	reserve_keys := clamp(expected_keys, 0, capacity)

	c.capacity = capacity
	c.nodes = make([dynamic]Node, 1, reserve_keys + 1, allocator)
	c.index = make(map[string]Node_Index, reserve_keys, allocator)
	c.free = SENTINEL
	c.nodes[SENTINEL].prev = SENTINEL
	c.nodes[SENTINEL].next = SENTINEL
}

@(private)
cache_destroy :: proc(c: ^Cache) {
	delete(c.nodes)
	delete(c.index)
	c^ = {}
}

@(private)
cache_len :: proc(c: ^Cache) -> int {
	return len(c.index)
}

// Inserts or overwrites `key`, making it the most recently used entry, and
// evicts the least recently used entry if the cache is over capacity.
@(private)
cache_set :: proc(c: ^Cache, key, value: string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		move_to_front(c, i)
		return
	}

	if len(c.index) >= c.capacity {
		evict_lru(c)
	}

	i := alloc_node(c)
	c.nodes[i].key = key
	c.nodes[i].value = value
	link_front(c, i)
	c.index[key] = i
}

// Looks up `key`; a hit makes it the most recently used entry.
@(private)
cache_get :: proc(c: ^Cache, key: string) -> (value: string, ok: bool) {
	i := c.index[key] or_return
	move_to_front(c, i)
	return c.nodes[i].value, true
}

// Removes `key`, reporting whether it was present.
@(private)
cache_del :: proc(c: ^Cache, key: string) -> (was_present: bool) {
	_, i := delete_key(&c.index, key)
	if i == SENTINEL {
		return false
	}
	unlink(c, i)
	free_node(c, i)
	return true
}

@(private = "file")
evict_lru :: proc(c: ^Cache) {
	lru := c.nodes[SENTINEL].prev
	assert(lru != SENTINEL)
	delete_key(&c.index, c.nodes[lru].key)
	unlink(c, lru)
	free_node(c, lru)
}

@(private = "file")
alloc_node :: proc(c: ^Cache) -> Node_Index {
	if c.free != SENTINEL {
		i := c.free
		c.free = c.nodes[i].next
		return i
	}
	append(&c.nodes, Node{})
	return Node_Index(len(c.nodes) - 1)
}

@(private = "file")
free_node :: proc(c: ^Cache, i: Node_Index) {
	c.nodes[i] = Node {
		next = c.free,
	}
	c.free = i
}

@(private = "file")
unlink :: proc(c: ^Cache, i: Node_Index) {
	n := &c.nodes[i]
	c.nodes[n.prev].next = n.next
	c.nodes[n.next].prev = n.prev
}

@(private = "file")
link_front :: proc(c: ^Cache, i: Node_Index) {
	first := c.nodes[SENTINEL].next
	c.nodes[i].prev = SENTINEL
	c.nodes[i].next = first
	c.nodes[first].prev = i
	c.nodes[SENTINEL].next = i
}

@(private = "file")
move_to_front :: proc(c: ^Cache, i: Node_Index) {
	if c.nodes[SENTINEL].next == i {
		return
	}
	unlink(c, i)
	link_front(c, i)
}

// `./app lru`: see the "lru" section of SPEC.md.
package lru

import "core:bufio"
import "core:fmt"
import "core:io"
import "core:os"
import "core:strconv"
import "core:strings"

import "../ioutil"

@(private = "file")
MAX_CAPACITY :: 1_000_000

@(private = "file")
OUTPUT_BUFFER_SIZE :: 64 * 1024

// Reads standard input, writes standard output and returns the exit status.
run :: proc() -> (exit_code: int) {
	input, read_err := ioutil.read_all(os.stdin)
	if read_err != nil {
		fmt.eprintln("lru: reading standard input:", read_err)
		return 1
	}
	defer delete(input)

	out: bufio.Writer
	bufio.writer_init(&out, os.to_writer(os.stdout), OUTPUT_BUFFER_SIZE)
	defer bufio.writer_destroy(&out)

	ok := simulate(string(input), bufio.writer_to_writer(&out))
	if flush_err := bufio.writer_flush(&out); flush_err != nil {
		fmt.eprintln("lru: writing standard output:", flush_err)
		return 1
	}
	return 0 if ok else 1
}

// Runs the commands in `input` (capacity line first) and writes their output
// to `w`. Keys and values held by the cache are slices of `input`.
@(private = "file")
simulate :: proc(input: string, w: io.Writer) -> (ok: bool) {
	rest := input
	header, _ := next_line(&rest)
	capacity, cap_ok := strconv.parse_int(strings.trim_space(header), 10)
	if !cap_ok || capacity < 1 || capacity > MAX_CAPACITY {
		fmt.eprintfln("lru: invalid capacity %q", header)
		return false
	}

	cache: Cache
	cache_init(&cache, capacity, strings.count(rest, "\n") + 1)
	defer cache_destroy(&cache)

	for line in next_line(&rest) {
		args := line
		command := next_token(&args)
		switch command {
		case "SET":
			key := next_token(&args)
			value := next_token(&args)
			cache_set(&cache, key, value)
		case "GET":
			key := next_token(&args)
			if value, hit := cache_get(&cache, key); hit {
				io.write_string(w, value)
			} else {
				io.write_string(w, "NULL")
			}
			io.write_byte(w, '\n')
		case "DEL":
			key := next_token(&args)
			io.write_string(w, "1\n" if cache_del(&cache, key) else "0\n")
		case "SIZE":
			io.write_int(w, cache_len(&cache))
			io.write_byte(w, '\n')
		case "":
		// Blank line: nothing to do.
		case:
			fmt.eprintfln("lru: unknown command %q", command)
		}
	}
	return true
}

// Pops the next line off `s`, without its terminator ("\n" or "\r\n").
// The last line may lack a terminator.
@(private = "file")
next_line :: proc(s: ^string) -> (line: string, ok: bool) {
	if len(s) == 0 {
		return "", false
	}
	if i := strings.index_byte(s^, '\n'); i >= 0 {
		line, s^ = s[:i], s[i + 1:]
	} else {
		line, s^ = s^, ""
	}
	return strings.trim_suffix(line, "\r"), true
}

// Pops the next space-separated token off `s`.
@(private = "file")
next_token :: proc(s: ^string) -> (token: string) {
	if i := strings.index_byte(s^, ' '); i >= 0 {
		token, s^ = s[:i], s[i + 1:]
	} else {
		token, s^ = s^, ""
	}
	return
}

// Entry point of ./app: dispatches the first argument to a subcommand.
//
// Each subcommand lives in its own package under src/ and exposes
//
//     run :: proc() -> (exit_code: int)
//
// which reads standard input, writes standard output and returns the
// process exit status.
package main

import "core:fmt"
import "core:os"

import "calc"
import "lru"
import "wordfreq"

Subcommand :: struct {
	name: string,
	run:  proc() -> (exit_code: int),
}

SUBCOMMANDS :: [?]Subcommand {
	{"wordfreq", wordfreq.run},
	{"lru",      lru.run},
	{"calc",     calc.run},
}

EXIT_USAGE :: 2

main :: proc() {
	os.exit(dispatch(os.args))
}

dispatch :: proc(args: []string) -> (exit_code: int) {
	if len(args) < 2 {
		usage(args)
		return EXIT_USAGE
	}

	name := args[1]
	for cmd in SUBCOMMANDS {
		if cmd.name == name {
			return cmd.run()
		}
	}

	fmt.eprintfln("unknown subcommand: %q", name)
	usage(args)
	return EXIT_USAGE
}

usage :: proc(args: []string) {
	program := len(args) > 0 ? args[0] : "app"
	fmt.eprintf("usage: %s <subcommand>\n\nsubcommands:\n", program)
	for cmd in SUBCOMMANDS {
		fmt.eprintfln("  %s", cmd.name)
	}
}

// `./app wordfreq`: see the "wordfreq" section of SPEC.md.
//
// Reads all of standard input, counts case-folded runs of ASCII letters and
// prints the TOP_N most frequent as `<count> <word>` lines, ordered by count
// descending, then word ascending.
package wordfreq

import "core:fmt"
import "core:os"
import "core:strings"

import "../ioutil"

@(private)
TOP_N :: 10

@(private)
Entry :: struct {
	word:  string,
	count: int,
}

// Reads standard input, writes standard output and returns the exit status.
run :: proc() -> (exit_code: int) {
	data, err := ioutil.read_all(os.stdin)
	defer delete(data)
	if err != nil {
		fmt.eprintln("wordfreq: reading standard input:", err)
		return 1
	}

	counts := count_words(data)
	defer delete(counts)

	top: [TOP_N]Entry
	n := top_entries(counts, top[:])

	b := strings.builder_make()
	defer strings.builder_destroy(&b)
	for e in top[:n] {
		strings.write_int(&b, e.count)
		strings.write_byte(&b, ' ')
		strings.write_string(&b, e.word)
		strings.write_byte(&b, '\n')
	}
	if _, werr := os.write_string(os.stdout, strings.to_string(b)); werr != nil {
		fmt.eprintln("wordfreq: writing standard output:", werr)
		return 1
	}
	return 0
}

// Lowercases every word of `data` in place and counts it. The map keys are
// slices of `data`, which must therefore outlive the returned map.
@(private)
count_words :: proc(data: []byte, allocator := context.allocator) -> map[string]int {
	counts := make(map[string]int, allocator)
	i := 0
	for i < len(data) {
		if !is_letter(data[i]) {
			i += 1
			continue
		}
		start := i
		for i < len(data) && is_letter(data[i]) {
			data[i] |= 0x20 // ASCII letters: setting bit 5 lowercases.
			i += 1
		}
		counts[string(data[start:i])] += 1
	}
	return counts
}

@(private)
is_letter :: #force_inline proc "contextless" (c: byte) -> bool {
	return (c | 0x20) - 'a' < 26
}

// Strict ranking order: higher count first, then lexicographically smaller word.
@(private)
ranks_before :: #force_inline proc(a, b: Entry) -> bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// Fills `top` with the best `len(top)` entries of `counts` in ranking order
// and returns how many were filled.
@(private)
top_entries :: proc(counts: map[string]int, top: []Entry) -> (n: int) {
	for word, count in counts {
		e := Entry{word, count}
		if n == len(top) {
			if !ranks_before(e, top[n - 1]) {
				continue
			}
		} else {
			n += 1
		}
		// Insertion step: shift worse entries down one slot.
		j := n - 1
		for j > 0 && ranks_before(e, top[j - 1]) {
			top[j] = top[j - 1]
			j -= 1
		}
		top[j] = e
	}
	return n
}
